-- Outsourcing Canario — esquema MySQL 8. Datos 100% ficticios.
CREATE TABLE IF NOT EXISTS organizations (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL, industry VARCHAR(60) DEFAULT '', country VARCHAR(60) DEFAULT '', size VARCHAR(20) DEFAULT '', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL, email VARCHAR(160) NOT NULL UNIQUE, password_hash VARCHAR(200) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'client', organization_id INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_user_org FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS sessions (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_sess_user FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS password_resets (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, used TINYINT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS services (id INT AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, summary TEXT, benefits JSON, capabilities JSON, modalities JSON, stack JSON);
CREATE TABLE IF NOT EXISTS industries (id INT AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, description TEXT);
CREATE TABLE IF NOT EXISTS case_studies (id INT AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(80) NOT NULL UNIQUE, company VARCHAR(120) NOT NULL, industry VARCHAR(60) NOT NULL, service VARCHAR(80) NOT NULL, problem TEXT, solution TEXT, result TEXT);
CREATE TABLE IF NOT EXISTS jobs (id INT AUTO_INCREMENT PRIMARY KEY, slug VARCHAR(90) NOT NULL UNIQUE, title VARCHAR(140) NOT NULL, area VARCHAR(60), modality VARCHAR(30), level VARCHAR(30), location VARCHAR(80), tech VARCHAR(200), status VARCHAR(20) DEFAULT 'abierta', description TEXT);
CREATE TABLE IF NOT EXISTS job_applications (id INT AUTO_INCREMENT PRIMARY KEY, job_id INT NOT NULL, name VARCHAR(80), last_name VARCHAR(80), email VARCHAR(160), phone VARCHAR(40) DEFAULT '', country VARCHAR(60) DEFAULT '', experience VARCHAR(60) DEFAULT '', profile TEXT, portfolio_url VARCHAR(300) DEFAULT '', cover_letter TEXT, cv_file_name VARCHAR(200) DEFAULT '', status VARCHAR(30) DEFAULT 'recibida', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_app_job FOREIGN KEY (job_id) REFERENCES jobs(id));
CREATE TABLE IF NOT EXISTS contact_leads (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120), email VARCHAR(160), phone VARCHAR(40) DEFAULT '', company VARCHAR(160) DEFAULT '', department VARCHAR(80) DEFAULT '', subject VARCHAR(160) DEFAULT '', message TEXT, contact_preference VARCHAR(30) DEFAULT 'correo', status VARCHAR(30) DEFAULT 'nuevo', request_code VARCHAR(30), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS quote_requests (id INT AUTO_INCREMENT PRIMARY KEY, company VARCHAR(160), industry VARCHAR(60) DEFAULT '', country VARCHAR(60) DEFAULT '', size VARCHAR(20) DEFAULT '', contact_name VARCHAR(120), email VARCHAR(160), service_slug VARCHAR(80), problem TEXT, professionals INT DEFAULT 1, technologies VARCHAR(300) DEFAULT '', modality VARCHAR(40) DEFAULT '', start_date VARCHAR(20) DEFAULT '', duration VARCHAR(40) DEFAULT '', budget VARCHAR(40) DEFAULT '', priority VARCHAR(20) DEFAULT 'media', comments TEXT, status VARCHAR(30) DEFAULT 'nueva', request_code VARCHAR(30), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS projects (id INT AUTO_INCREMENT PRIMARY KEY, organization_id INT NOT NULL, name VARCHAR(160) NOT NULL, status VARCHAR(30) DEFAULT 'activo', priority VARCHAR(20) DEFAULT 'media', manager VARCHAR(120) DEFAULT '', start_date VARCHAR(20) DEFAULT '', target_date VARCHAR(20) DEFAULT '', progress INT DEFAULT 0, description TEXT, CONSTRAINT fk_proj_org FOREIGN KEY (organization_id) REFERENCES organizations(id));
CREATE TABLE IF NOT EXISTS consultants (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(140) NOT NULL, specialty VARCHAR(90), years INT DEFAULT 0, availability VARCHAR(40) DEFAULT 'Disponible', status VARCHAR(20) DEFAULT 'activo', skills VARCHAR(90) DEFAULT '');
CREATE TABLE IF NOT EXISTS talent_directory (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(140) NOT NULL, specialty VARCHAR(90), years INT DEFAULT 0, availability VARCHAR(40) DEFAULT 'Disponible', skills VARCHAR(90) DEFAULT '');
-- Vista pública del Escenario B: SOLO columnas no sensibles.
CREATE OR REPLACE VIEW talent_public AS SELECT id, name, specialty, years, availability, skills FROM talent_directory;
CREATE TABLE IF NOT EXISTS project_members (id INT AUTO_INCREMENT PRIMARY KEY, project_id INT NOT NULL, consultant_id INT NOT NULL, role_in_project VARCHAR(80) DEFAULT 'Asignado');
CREATE TABLE IF NOT EXISTS project_milestones (id INT AUTO_INCREMENT PRIMARY KEY, project_id INT NOT NULL, title VARCHAR(160), due_date VARCHAR(20) DEFAULT '', done TINYINT DEFAULT 0);
CREATE TABLE IF NOT EXISTS tickets (id INT AUTO_INCREMENT PRIMARY KEY, organization_id INT NULL, user_id INT NULL, subject VARCHAR(180), category VARCHAR(60) DEFAULT 'Soporte', priority VARCHAR(20) DEFAULT 'media', description TEXT, status VARCHAR(30) DEFAULT 'abierto', assignee VARCHAR(120) DEFAULT '', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ticket_comments (id INT AUTO_INCREMENT PRIMARY KEY, ticket_id INT NOT NULL, user_id INT NULL, body TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS documents (id INT AUTO_INCREMENT PRIMARY KEY, organization_id INT NULL, title VARCHAR(180), type VARCHAR(40) DEFAULT 'reporte', file_name VARCHAR(200) DEFAULT '', size_bytes INT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS invoices (id INT AUTO_INCREMENT PRIMARY KEY, organization_id INT NULL, number VARCHAR(30), concept VARCHAR(200), amount DECIMAL(12,2) DEFAULT 0, currency VARCHAR(10) DEFAULT 'USD', status VARCHAR(20) DEFAULT 'pendiente', issued_date VARCHAR(20) DEFAULT '');
CREATE TABLE IF NOT EXISTS activities (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, organization_id INT NULL, action VARCHAR(80), detail VARCHAR(300) DEFAULT '', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
